const email = String($json.email || '').trim();
const subject = String($json.email_subject || '').trim();
const body = String($json.email_body || '').trim();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
const contentValid = subject.length > 0 && body.length > 0;

return [{
  json: {
    ...$json,
    email,
    email_valid: emailValid && contentValid,
    validation_error: !emailValid
      ? 'Invalid recipient email address'
      : (!contentValid ? 'Approved email subject or body is empty' : null)
  }
}];

const lead = $('Code — Validate Approved Email').item.json;
const errorValue = $json.error;
const sendSuccess = !errorValue;
let smtpResponse;

if (sendSuccess) {
  try {
    smtpResponse = JSON.stringify($json || {}).slice(0, 2000);
  } catch (_e) {
    smtpResponse = 'SMTP accepted the message';
  }
} else {
  smtpResponse = String(errorValue.message || errorValue.description || errorValue).slice(0, 2000);
}

return [{
  json: {
    ...lead,
    send_success: sendSuccess,
    smtp_response: smtpResponse || (sendSuccess ? 'SMTP accepted the message' : 'Unknown SMTP error'),
    send_error: sendSuccess ? null : (smtpResponse || 'Unknown SMTP error')
  }
}];

const cfg = $('config').first().json;
const start = new Date(cfg.runStartTs).getTime();
const durationMs = Number.isFinite(start) ? Date.now() - start : 0;

return [{
  json: {
    run_start_ts: cfg.runStartTs,
    duration_ms: durationMs,
    notes: 'WF4 email_send batch completed at ' + new Date().toISOString()
  }
}];
